def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)

    active = [any(x != bg for x in row) for row in grid]
    runs = []
    r = 0
    while r < h:
        if not active[r]:
            r += 1
            continue
        start = r
        while r < h and active[r]:
            r += 1
        runs.append((start, r))

    out = [row[:] for row in grid]
    for i, (a, b) in enumerate(runs):
        for c, d in runs[i + 1:]:
            if b - a != d - c:
                continue
            for k in range(b - a):
                for col in range(w):
                    x, y = grid[a + k][col], grid[c + k][col]
                    if x == bg and y != bg:
                        out[a + k][col] = 1
                    elif y == bg and x != bg:
                        out[c + k][col] = 1
    return out
